lib='''def bbox_cells(grid, color):
    """All cells of a color, plus its bounding box."""
    cells=[(i,j) for i,r in enumerate(grid) for j,v in enumerate(r) if v==color]
    rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
    return cells,(min(rs),max(rs),min(cs),max(cs))

def is_rect_border(grid, color):
    """True if the color's cells exactly trace the border of their bounding box."""
    cells,(r0,r1,c0,c1)=bbox_cells(grid,color)
    return len(cells)==2*(r1-r0+1)+2*(c1-c0-1) and all(i in (r0,r1) or j in (c0,c1) for i,j in cells)

def checkerboard_fill(grid, color, dot, parity=0):
    """Fill the interior of the color's rectangle border with a checkerboard of dot, starting at the interior top-left when parity=0."""
    _,(r0,r1,c0,c1)=bbox_cells(grid,color)
    g=[row[:] for row in grid]
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            if (i+j-r0-c0)%2==parity:
                g[i][j]=dot
    return g

def rect_capacity(r0, r1, c0, c1):
    """Number of cells of one checkerboard parity inside the interior of a rectangle border."""
    return ((r1-r0-1)*(c1-c0-1)+1)//2

def assign_by_count(grid):
    """Map each non-rectangle color to the rectangle whose checkerboard capacity equals its cell count; returns (rects dict color->bbox, assignment dict dot->rect color)."""
    colors={v for r in grid for v in r if v}
    rects={c:bbox_cells(grid,c)[1] for c in colors if is_rect_border(grid,c)}
    from collections import Counter
    dots=Counter(v for r in grid for v in r if v and v not in rects)
    caps={c:rect_capacity(*b) for c,b in rects.items()}
    assign={}
    for d,n in dots.items():
        match=[c for c,cap in caps.items() if cap==n]
        assert len(match)==1,(d,n,caps)
        assign[d]=match[0]
    return rects,assign
'''
